SELECT log_name, cmdb_id, count(*) n FROM 'datasets/OpenRCA/data/bank/parquet/log_service.parquet'
WHERE day BETWEEN DATE '2021-03-03' AND DATE '2021-03-05' AND log_name NOT LIKE '%access_log'
GROUP BY 1,2 ORDER BY 1,3 DESC;

SELECT scoring_points FROM (
  SELECT row_number() OVER () AS task_id, scoring_points
  FROM read_csv('datasets/OpenRCA/data/bank/query.csv')
) WHERE task_id = 1;
